html:
{% for page in layout %}
<div class="page-break angebot-wrapper">
	<style>
		.angebot-wrapper {
			font-family: "Inter", Arial, sans-serif;
			color: #1a1a1a;
			font-size: 12px;
		}
		.print-format-body {
			padding: 6px 4px !important;
		}
		body {
			margin-bottom: 0mm !important;
			padding: 0px !important;
		}
		.doc-title {
			font-size: 26px;
			font-weight: 700;
			margin: 0;
			color: #1a1a1a;
		}
		.doc-number {
			font-size: 13px;
			color: #5b6b8c;
			margin: 2px 0 10px 0;
		}
		.header-logo-wrap {
			text-align: center;
			margin: 10px 0 10px 0;
		}
		.header-logo-wrap img {
			width: 100%;
			height: auto;
			display: block;
		}
		.title-rule {
			border-top: 1px solid #d0d0d0;
			margin-bottom: 18px;
		}
		.address-date-table {
			width: 100%;
			margin-bottom: 18px;
		}
		.address-date-table td {
			vertical-align: top;
		}
		.text-muted {
			color: #7c7c7c;
		}
		.text-right {
			text-align: right;
		}
		.text-center {
			text-align: center;
		}
		.text-bold {
			font-weight: bold;
		}
		p.intro {
			margin: 4px 0 14px 0;
		}
		table.items-table {
			width: 100%;
			table-layout: fixed;
			border-collapse: collapse;
			margin-bottom: 10px;
		}
		table.items-table th,
		table.items-table td {
			border: 1px solid #cfcfcf;
			padding: 4px 6px;
			font-size: 10.5px;
			vertical-align: top;
			word-wrap: break-word;
			overflow-wrap: break-word;
		}
		table.items-table thead th {
			background: #f5f5f5;
			font-weight: bold;
			text-align: left;
		}
		tr.main-row td {
			border-bottom: 0;
		}
		tr.main-row.main-last td {
			border-bottom: 1px solid #cfcfcf;
		}
		tr.sub-row td {
			border-top: 0;
			border-bottom: 0;
			font-size: 10px;
			font-style: italic;
			color: #8c8c8c;
			padding-top: 2px;
			padding-bottom: 2px;
		}
		tr.sub-row.sub-last td {
			border-bottom: 1px solid #cfcfcf;
		}
		.sub-label {
			padding-left: 18px !important;
		}
		.sub-value {
			font-weight: 400;
		}
		.sub-text {
			color: #8c8c8c;
		}
		.col-pos { width: 6%; white-space: nowrap; }
		.col-teilenummer { width: 13%; }
		.col-name { width: 17%; }
		.col-desc { width: 22%; }
		.col-qty { width: 9%; white-space: nowrap; }
		.col-rate { width: 11%; white-space: nowrap; }
		.col-amount { width: 12%; white-space: nowrap; }

		table.bottom-table {
			width: 100%;
			margin-top: 20px;
			page-break-inside: avoid;
			break-inside: avoid;
		}
		table.bottom-table > tbody > tr > td {
			vertical-align: top;
		}
		.terms-cell {
			width: 60%;
			padding-right: 20px;
		}
		table.totals-table {
			width: 100%;
		}
		table.totals-table td {
			padding: 4px 0;
			border-bottom: 1px solid #e5e5e5;
		}
		table.totals-table tr.grand-total td {
			border-bottom: none;
			border-top: 1px solid #1a1a1a;
			font-weight: bold;
			padding-top: 8px;
		}

		/* Footer-Styles liegen direkt im #footer-html Block (siehe unten),
		   da wkhtmltopdf --footer-html als eigenstaendiges Dokument rendert. */
	</style>

	{% if loop.index == 1 %}
	{% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
	{% if company_logo %}
	<div class="header-logo-wrap">
		<img src="{{ frappe.utils.get_url(company_logo) }}" />
	</div>
	{% endif %}
	<div class="title-rule"></div>
	<div class="text-right" style="margin-bottom: 18px;">
		<h1 class="doc-title">{{ _("Angebot") }}</h1>
		<div class="doc-number">{{ doc.name }}</div>
	</div>

	<table class="address-date-table">
		<tr>
			<td style="width: 60%">
				{% set delivery_address_name = doc.shipping_address_name or doc.customer_address %}
				{% if delivery_address_name %}
					{% set customer_address = frappe.db.get_value("Address", delivery_address_name, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
					<b>{{ doc.customer_name }}</b><br>
					{{ customer_address.address_line1 or "" }}<br>
					{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}
					{{ customer_address.pincode or "" }} {{ customer_address.city or "" }}<br>
					{{ customer_address.country or "" }}
				{% else %}
					<b>{{ doc.customer_name }}</b>
				{% endif %}
			</td>
			<td style="width: 40%" class="text-right">
				<span class="text-muted">{{ _("Datum") }}:</span><br>
				{{ frappe.utils.format_date(doc.transaction_date) }}
			</td>
		</tr>
	</table>

	{% set contact = frappe.get_doc("Contact", doc.contact_person) if doc.contact_person else None %}
	{% set anrede = None %}
	{% if contact %}
		{% if contact.salutation == "Mr" %}{% set anrede = "Herr" %}
		{% elif contact.salutation in ("Mrs", "Ms", "Madam", "Miss") %}{% set anrede = "Frau" %}
		{% endif %}
	{% endif %}
	<p class="intro">
		{% if anrede and contact.last_name %}
			Sehr geehrte{{ "r" if anrede == "Herr" else "" }} {{ anrede }} {{ contact.last_name }},
		{% else %}
			Sehr geehrte Damen und Herren,
		{% endif %}
		<br><br>
		wir bedanken uns für Ihre Anfrage und unterbreiten Ihnen folgendes Angebot:
	</p>

	<!-- Items Table -->
	{% macro de_money(v) -%}
		{{ "{:,.2f}".format((v or 0) | float) | replace(",", "X") | replace(".", ",") | replace("X", ".") }}
	{%- endmacro %}
	{% set sonderkosten_labels = {
		"ART-Rüstkosten-Hohenstein GmbH": "Rüstkosten",
		"ART-Messkosten-Hohenstein GmbH": "Messkosten",
		"ART-Einmalkosten-Hohenstein GmbH": "Einmalkosten",
		"ART-Expresskosten-Hohenstein GmbH": "Expresskosten"
	} %}
	{% set main_items = doc.items | selectattr("item_group", "ne", "Sonderkosten") | list %}
	<table class="items-table">
		<thead>
			<tr>
				<th class="col-pos text-center">{{ _("Pos") }}</th>
				<th class="col-teilenummer">{{ _("Teilenummer") }}</th>
				<th class="col-name">{{ _("Artikelbezeichnung") }}</th>
				<th class="col-desc">{{ _("Beschreibung") }}</th>
				<th class="col-qty text-right">{{ _("Menge") }}</th>
				<th class="col-rate text-right">{{ _("Preis (EUR)") }}</th>
				<th class="col-amount text-right">{{ _("Betrag (EUR)") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for main in main_items %}
			{% set teilenummer = frappe.db.get_value("Item", main.item_code, "custom_teilenummer") %}
			{% set sub_rows = (doc.items | selectattr("item_group", "eq", "Sonderkosten") | selectattr("custom_parent_item_id", "eq", main.custom_parent_item_id) | list) if main.custom_parent_item_id else [] %}
			<tr class="main-row {% if not sub_rows %}main-last{% endif %}">
				<td class="pos text-center">{{ loop.index }}</td>
				<td>{{ teilenummer or main.item_code }}</td>
				<td>{{ main.item_name }}</td>
				<td class="desc">{{ frappe.utils.strip_html(main.description) if main.description else "" }}</td>
				<td class="text-right">{{ main.get_formatted("qty", 0) }}</td>
				<td class="text-right">{{ de_money(main.net_rate) }}</td>
				<td class="text-right">{{ de_money(main.net_amount) }}</td>
			</tr>
			{% for sub in sub_rows %}
			{% set label = sonderkosten_labels.get(sub.item_code, sub.item_name) %}
			{% set extra_text = frappe.utils.strip_html(sub.description) if sub.description and sub.description != sub.item_name else "" %}
			<tr class="sub-row {% if loop.last %}sub-last{% endif %}">
				<td></td>
				<td colspan="3" class="sub-label">↳ {{ teilenummer or main.item_code }} {{ label }}{% if extra_text %} <span class="sub-text">„{{ extra_text }}"</span>{% endif %}</td>
				<td class="text-right"></td>
				<td class="text-right"></td>
				<td class="text-right sub-value">+ {{ de_money(sub.net_amount) }}</td>
			</tr>
			{% endfor %}
			{% endfor %}
		</tbody>
	</table>
	{% endif %}

	{% if loop.index == layout|len %}
	<table class="bottom-table">
		<tr>
			<td class="terms-cell">
				{% if doc.terms %}
					{{ doc.terms }}
				{% endif %}
				<br>
				Über eine Auftragserteilung würden wir uns freuen und verbleiben<br><br>
				Mit freundlichen Grüßen<br>
				{{ frappe.db.get_value("User", doc.owner, "full_name") or "" }}
			</td>
			<td style="width: 40%">
				<table class="totals-table">
					<tr>
						<td class="text-muted">{{ _("Netto Summe") }}</td>
						<td class="text-right">{{ "{:,.2f}".format(doc.net_total)|replace(",", "X")|replace(".", ",")|replace("X", ".") }} EUR</td>
					</tr>
					{%- for tax in doc.taxes -%}
						{%- if tax.tax_amount -%}
						<tr>
							<td class="text-muted">{{ tax.description }}</td>
							<td class="text-right">{{ "{:,.2f}".format(tax.tax_amount)|replace(",", "X")|replace(".", ",")|replace("X", ".") }} EUR</td>
						</tr>
						{%- endif -%}
					{%- endfor -%}
					<tr class="grand-total">
						<td>{{ _("Gesamtbetrag") }}</td>
						<td class="text-right">{{ "{:,.2f}".format(doc.grand_total)|replace(",", "X")|replace(".", ",")|replace("X", ".") }} EUR</td>
					</tr>
				</table>
			</td>
		</tr>
	</table>
	{% endif %}

	{% set company_details = frappe.db.get_value("Company", doc.company, ["website", "email", "phone_no", "tax_id"], as_dict=True) %}
	<div {% if print_settings.repeat_header_footer %} id="footer-html" class="visible-pdf" {% endif %}>
		<style>
			/* wkhtmltopdf rendert --footer-html als eigenstaendiges Dokument -
			   das <style> der Hauptseite wird NICHT mit uebernommen, daher hier dupliziert. */
			#footer-html {
				font-size: 5px;
				color: #333;
				font-family: "Inter", Arial, sans-serif;
			}
			.footer-doc-tag {
				color: #7c7c7c;
				margin-bottom: 1px;
			}
			.footer-rule {
				border-top: 1px solid #b03030;
				margin-bottom: 0.01mm;
			}
			table.footer-table {
				width: 100%;
			}
			table.footer-table td {
				vertical-align: top;
				line-height: 1.2;
				padding-top: 2px;
			}
			.footer-table b {
				display: block;
				margin-bottom: 1px;
			}
			p.page-number {
				font-size: 5px;
				color: #7c7c7c;
				margin-top: 3px;
				text-align: center;
			}
		</style>
		<div class="footer-doc-tag">{{ _("Angebot") }}<br>{{ doc.name }}</div>
		<div class="footer-rule"></div>
		<table class="footer-table" width="100%" cellpadding="0" cellspacing="0">
			<tr>
				<td width="28%">
					<b>HOHENSTEIN GmbH</b>
					Schindelmacherweg 22<br>
					74535 Mainhardt-<br>Hohenstraßen<br>
					HRB 571584<br>Amtsgericht Stuttgart<br>
					UST-ID-Nr.: {{ company_details.tax_id or "DE224416172" }}
				</td>
				<td width="32%">
					<b>Telefon {{ company_details.phone_no or "07903 / 3678" }}</b>
					{{ company_details.email or "info@cnc-hohenstein.de" }}<br>
					{{ company_details.website or "www.cnc-hohenstein.de" }}<br>
					Geschäftsführer:<br>Bernhard Hohenstein
				</td>
				<td width="40%">
					<b>Sparkasse SHA</b>
					IBAN DE64 6225 0030 0005 4437 72<br><br>
					<b>VR Bank SHA</b>
					IBAN DE50 6229 0110 0502 1440 09
				</td>
			</tr>
		</table>
		<p class="text-center page-number">
			{{ _("Seite {0} von {1}").format('<span class="page"></span>', '<span class="topage"></span>') }}
		</p>
	</div>
</div>
{% endfor %}
